class ThroughputException(Exception):
    pass


class TableParser:
    """
    Class that interacts with Egate interface
    """

    def _extract_table(self, egate_output):
        extract_table_pattern = "===+.*?===+"
        return re.search(extract_table_pattern, egate_output, re.DOTALL).group(0)

    def _extract_header_from_table(self, table):
        table_header_pattern = r"((\w+([ -.]\w+)*)\s\s+)+(\w+([ -.]\w+)*)"
        header = re.search(table_header_pattern, table).group()
        return re.split(r"\s\s+", header)

    def _get_rows_from_table(self, header_list, table):
        one_posititon_in_table_pattern = r"(\w+([ -.]\w+)*)"
        separator_pattern = r"\s\s+"
        row_in_table_pattern = (
            '('
            + one_posititon_in_table_pattern
            + separator_pattern
            + '){'
            + str(len(header_list) - 1)
            + '}'
            + one_posititon_in_table_pattern
        )
        rows_with_header = [g.group(0) for g in re.finditer(row_in_table_pattern, table)]
        rows_in_table = rows_with_header[1:] if len(rows_with_header) > 1 else []
        return rows_in_table

    def parse_egate_table(self, egate_output):
        """
        Parse egate table
        :param egate_output:    egate_output
        :return:                dictionary with parsed table
        """
        separator_pattern = r"\s\s+"
        table = self._extract_table(egate_output)
        header_list = self._extract_header_from_table(table)
        rows = self._get_rows_from_table(header_list, table)
        result_dictionaries_list = []
        for i in rows:
            row = re.split(separator_pattern, i)
            result_dictionaries_list.append(dict(list(zip(header_list, row))))
        return result_dictionaries_list
